    public static void Run(MainWindow w,string folder,Action<bool,string> check)
    {
        object? Call(string name,params object?[] args){var method=typeof(MainWindow).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public)!;return method.Invoke(w,method.GetParameters().Select((p,i)=>i<args.Length?args[i]:p.DefaultValue).ToArray());}
        T C<T>(string name)=>(T)w.FindName(name);void Pump()=>Dispatcher.CurrentDispatcher.Invoke(()=>{},DispatcherPriority.ApplicationIdle);
        void Await(Task task){var clock=System.Diagnostics.Stopwatch.StartNew();while(!task.IsCompleted&&clock.ElapsedMilliseconds<15000){Pump();Thread.Sleep(10);}if(!task.IsCompleted)throw new TimeoutException("live separation did not finish");task.GetAwaiter().GetResult();Pump();}
        using var image=new SKBitmap(240,100);image.Erase(new(125,20,32));using(var canvas=new SKCanvas(image))using(var p=new SKPaint{Color=SKColors.White,Style=SKPaintStyle.Stroke,StrokeWidth=4,IsAntialias=true}){canvas.DrawCircle(50,45,22,p);canvas.DrawRect(100,20,40,50,p);}
        var file=Path.Combine(folder,"v12 글자.png");SourceImage.SavePng(image,file);var region=new EffectRegion{Bounds=new(0,0,1,1),ContentOnly=true,SeparationTarget=SeparationTarget.Text,TextInkColor="#FFFFFF",TextSettings=new(){BackgroundColors=["#7D1420"]},Background=BackgroundMode.Solid,BackgroundColor="#7D1420",Clips=[new(){Duration=1,Options=new(){Kind=EffectKind.Zoom}}]};
        w.ApplyDocument(new(){Jobs=[new(){SourcePath=file,Width=240,Height=100,Regions=[region]}],Video=new()});Pump();check(C<ComboBox>("OutputKindBox").SelectedIndex==0&&C<ComboBox>("OutputKindBox").Items[0].ToString()!.Contains("OBS"),"OBS browser is the first output item and the default for new work");check(C<FrameworkElement>("WebmRepeatsPanel").Visibility==Visibility.Collapsed&&C<FrameworkElement>("WebmQualityPanel").Visibility==Visibility.Collapsed,"OBS-only mode hides WebM-only repeat count and CRF quality");C<ComboBox>("OutputKindBox").SelectedIndex=1;Pump();check(C<FrameworkElement>("WebmRepeatsPanel").Visibility==Visibility.Visible,"WebM output restores its finite repeat and quality settings");C<ComboBox>("PlaybackViewBox").SelectedIndex=0;Pump();check(C<CheckBox>("BroadcastPreviewCheck").IsChecked==true&&C<ComboBox>("PlaybackViewBox").Items[0].ToString()!.Contains("OBS"),"OBS broadcast preview is the first playback mode");
        var dialog=new ObjectSelectionWindow(image,region){Owner=w,WindowStartupLocation=WindowStartupLocation.Manual,Left=-16000,Top=-16000,ShowActivated=false,ShowInTaskbar=false};
        try
