            dialog.Show();Pump();dialog.TextMethod.SelectedIndex=1;Await(dialog.FlushPreviewAsync());check(dialog.SelectedTextSettings.RangeMode&&dialog.Canvas.Buffer.Alpha[45*240+50]==0,"changing the text method updates live preview without pressing recalculate");var old=dialog.RangeTolerance.Value;dialog.RangeTolerance.Value=65;Await(dialog.FlushPreviewAsync());check(dialog.SelectedTextSettings.ColorTolerance==65,"range slider immediately changes the displayed separation settings");dialog.Undo();check(dialog.RangeTolerance.Value==old,"precision undo restores the range slider and mask together");dialog.Redo();check(dialog.RangeTolerance.Value==65,"precision redo restores the changed separation options");
            dialog.Canvas.BrushSize=3;dialog.Canvas.PaintStroke([new(12,12)],true);check(dialog.Canvas.Buffer.Alpha[12*240+12]==255,"manual include stroke changes the current mask");dialog.RangeTolerance.Value=40;Await(dialog.FlushPreviewAsync());check(dialog.Canvas.Buffer.Alpha[12*240+12]==255,"live recomputation preserves the manual include patch");dialog.Undo();check(dialog.RangeTolerance.Value==65&&dialog.Canvas.Buffer.Alpha[12*240+12]==255,"undoing a slider gesture preserves the earlier brush stroke");dialog.Undo();check(dialog.Canvas.Buffer.Alpha[12*240+12]==0,"undoing the brush restores the original background hole");dialog.Redo();check(dialog.Canvas.Buffer.Alpha[12*240+12]==255,"redoing the brush restores its pixels and manual patch");
            check(dialog.PrepareResult()&&dialog.SelectedCutout!.ManualPng.Length>0,"manual brush overrides persist separately from the automatic result");var saved=region.Copy(false);saved.Cutout=dialog.SelectedCutout;saved.TextSettings=dialog.SelectedTextSettings;var reopened=new ObjectSelectionWindow(image,saved){Owner=w,WindowStartupLocation=WindowStartupLocation.Manual,Left=-16000,Top=-16000,ShowInTaskbar=false,ShowActivated=false};try{reopened.Show();Pump();reopened.RangeTolerance.Value=42;Await(reopened.FlushPreviewAsync());check(reopened.Canvas.Buffer.Alpha[12*240+12]==255,"reopened manual patches survive later automatic parameter changes");}finally{reopened.Close();}saved.Bounds=new(0,0,.5,1);var resized=new ObjectSelectionWindow(image,saved){Owner=w,WindowStartupLocation=WindowStartupLocation.Manual,Left=-16000,Top=-16000,ShowInTaskbar=false,ShowActivated=false};try{resized.Show();Pump();check(resized.Canvas.Buffer.Width==120&&resized.Canvas.Buffer.Alpha[12*120+6]>0,"resizing an existing separated region preserves its scaled manual mask");}finally{resized.Close();}
            StudioUiChecks.Capture(dialog,Path.Combine(folder,"precision-v120.png"),1120,800);
        }finally{dialog.Close();}
        var preview=C<PreviewControl>("Preview");C<CheckBox>("EffectsPreviewCheck").IsChecked=true;StudioUiChecks.Capture(w,Path.Combine(folder,"v12-cache-first.png"),1600,1040);var count=TextSeparation.Calculations;for(var i=0;i<5;i++){Call("SelectRegion",region);preview.InvalidateVisual();Pump();}check(TextSeparation.Calculations==count,"selecting an unchanged separated region does not trigger extraction");
        using var map=new SKBitmap(640,400);map.Erase(new(17,48,78));using(var c=new SKCanvas(map))using(var p=new SKPaint{Color=new(35,92,121),IsAntialias=true}){using var land=new SKPath();land.AddPoly([new(50,220),new(120,80),new(300,70),new(430,110),new(590,250),new(500,345),new(260,310),new(180,355)],true);c.DrawPath(land,p);using var font=new SKFont(SKTypeface.FromFamilyName("Malgun Gothic"),18);p.Color=SKColors.White;c.DrawText("여행 경로 미리보기",25,35,font,p);p.Color=new(137,193,215);c.DrawText("CITY A",70,300,font,p);c.DrawText("CITY B",280,85,font,p);c.DrawText("CITY C",500,300,font,p);}
        var route=TravelRoute.Example();var window=new TravelRouteWindow(map,route){Owner=w,WindowStartupLocation=WindowStartupLocation.Manual,Left=-16000,Top=-16000,ShowActivated=false,ShowInTaskbar=false};
        try
        {
            window.Show();Pump();window.Canvas.Viewport.Update(window.Canvas.ActualWidth,window.Canvas.ActualHeight,640,400,SKRect.Create(640,400));var at=window.Canvas.Viewport.ToScreen(new SKPoint((float)window.Route.Points[0].X*640,(float)window.Route.Points[0].Y*400));window.Canvas.Begin(at);window.Canvas.Move(at+new SKPoint(20,12));window.Canvas.End();check(window.Route.Points[0].X!=route.Points[0].X,"travel waypoint body drags to a new map position");window.Undo();check(window.Route.Points[0].X==route.Points[0].X,"travel waypoint drag is reversible");window.Canvas.Selected=1;window.InsertPoint();check(window.Route.Points.Count==4,"travel editor inserts a waypoint between existing points");window.MovePoint(1);check(window.Canvas.Selected==3,"travel editor reorders the selected waypoint");window.DeletePoint();check(window.Route.Points.Count==3,"travel editor deletes a waypoint while preserving its route");check(window.TimeSlider.Maximum==window.Route.Duration,"travel timeline length follows movement plus per-point dwell times");window.Route.Curved=true;typeof(TravelRouteWindow).GetMethod("InitializeCurveHandles",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(window,null);window.Canvas.Selected=0;var curveBefore=window.Route.Points[0].X;var curveAt=window.Canvas.Viewport.ToScreen(new SKPoint((float)curveBefore*640,(float)window.Route.Points[0].Y*400));window.Canvas.Begin(curveAt);window.Canvas.Move(curveAt+new SKPoint(15,0));window.Canvas.End();check(window.Route.Points[0].X!=curveBefore,"curved route endpoint drags its body rather than an unused zero-length handle");window.Undo();StudioUiChecks.Capture(window,Path.Combine(folder,"travel-editor-v120.png"),1280,900);
        }finally{window.Close();}
        var applyTimer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};applyTimer.Tick+=(_,_)=>{var editor=Application.Current.Windows.OfType<TravelRouteWindow>().FirstOrDefault();if(editor is null)return;applyTimer.Stop();editor.Route.Points=TravelRoute.Example().Points;editor.SetTotalDuration(7);editor.Route.Repeat=true;IEnumerable<Button> Buttons(DependencyObject item){for(var i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(item);i++){var child=System.Windows.Media.VisualTreeHelper.GetChild(item,i);if(child is Button b)yield return b;foreach(var nested in Buttons(child))yield return nested;}}var buttons=Buttons(editor).ToList();buttons.First(b=>Equals(b.Content,"내 여행 경로로 저장")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));buttons.First(b=>Equals(b.Content,"타임라인에 적용")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));};applyTimer.Start();Call("OpenTravelRoute",w,new RoutedEventArgs());Pump();
        var current=(ImageJob)typeof(MainWindow).GetField("_current",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(w)!;var inserted=current.Regions.First(r=>r.Clips.Any(c=>c.Route is not null));var routeClip=inserted.Clips.Single();check(inserted.OverlayOnly&&inserted.Background==BackgroundMode.KeepOriginal,"applying travel editor creates a separate overlay without replacing the selected map region");check(routeClip.Duration==routeClip.Route!.Duration&&routeClip.Section==ClipSection.Loop&&current.Playback.Enabled&&current.Playback.ByEffects,"travel apply links automatic timeline length and selected whole-route repeat to OBS sections");check(C<ListBox>("AssetList").Items.Cast<EffectAsset>().Any(a=>a.Clips.Any(c=>c.Route is not null)),"saving in the travel editor exposes a reusable route in the user asset library");check(current.Regions.Any(r=>r.Id==region.Id),"travel apply preserves existing image effects and regions");
        var oldId=routeClip.Id;var editTimer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};editTimer.Tick+=(_,_)=>{var editor=Application.Current.Windows.OfType<TravelRouteWindow>().FirstOrDefault();if(editor is null)return;editTimer.Stop();editor.Route.Points[0].Stop+=1;editor.Route.Repeat=false;void Click(DependencyObject item){for(var i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(item);i++){var child=System.Windows.Media.VisualTreeHelper.GetChild(item,i);if(child is Button b&&Equals(b.Content,"타임라인에 적용")){b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));return;}Click(child);}}Click(editor);};editTimer.Start();Call("OpenTravelRoute",w,new RoutedEventArgs());Pump();check(routeClip.Id==oldId&&routeClip.Duration==routeClip.Route!.Duration&&routeClip.Duration==7&&routeClip.Section==ClipSection.Intro,"re-editing route timing preserves its clip identity and preserves the total budget and commits the entrance mode");
        Call("SelectRegion",region);var stored=C<ListBox>("AssetList").Items.Cast<EffectAsset>().First(a=>a.Clips.Any(c=>c.Route is not null));C<ListBox>("AssetList").SelectedItem=stored;Call("InsertAsset",w,new RoutedEventArgs());Pump();var selected=(EffectRegion)typeof(MainWindow).GetField("_region",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(w)!;check(selected.OverlayOnly&&selected.Background==BackgroundMode.KeepOriginal&&selected.Clips.Any(c=>c.Route is not null),"inserting a saved travel asset keeps a separate map-preserving overlay");
    }
